const $ = (id) => document.getElementById(id);

const DEFAULT_LOGO_URL = new URL("./assets/cictt_logo.jpg", document.baseURI).href;


const LOGO_DATA_URL = "data:image/jpeg;base64,";

const form = $("teamForm");
const resetBtn = $("resetBtn");
const previewSection = $("previewSection");
const reportEl = $("report");
const errorBox = $("errorBox");
const generatedMeta = $("generatedMeta");
const toast = $("toast");
const pngBtn = $("pngBtn");

const borderStyle = $("borderStyle");
const borderWidth = $("borderWidth");
const borderRadius = $("borderRadius");
const borderColor = $("borderColor");

let lastData = null;
let _logoBitmap = null;
let _logoPreviewSrc = DEFAULT_LOGO_URL;

function clean(v) {
    return (v ?? "").toString().trim();
}

function escapeHtml(str) {
    return (str ?? "").toString().replace(/[&<>"']/g, (c) => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#039;"
    }[c]));
}

function showToast(msg) {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add("show");
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => toast.classList.remove("show"), 2200);
}

function getTeamData() {
    return {
        teamName: clean($("teamName")?.value),
        members: [
            { role: "TEAM LEADER / FOUNDER", name: clean($("m1Name")?.value), email: clean($("m1Email")?.value) },
            { role: "DEVELOPER", name: clean($("m2Name")?.value), email: clean($("m2Email")?.value) },
            { role: "DESIGNER", name: clean($("m3Name")?.value), email: clean($("m3Email")?.value) },
        ],
        generatedAt: new Date().toISOString(),
    };
}

function validate(data) {
    if (!data.teamName) return "Please enter the Startup Name / Team Name.";
    for (const m of data.members) {
        if (!m.name) return `Please enter the name for: ${m.role}`;
    }
    return "";
}

function getBorderOptions() {
    return {
        style: borderStyle?.value || "solid",
        width: Number(borderWidth?.value || 6),
        radius: Number(borderRadius?.value || 28),
        color: borderColor?.value || "#F05722"
    };
}

function applyBorderOptionsToPreview() {
    if (!reportEl) return;
    const o = getBorderOptions();
    reportEl.style.setProperty("--rc-bs", o.style);
    reportEl.style.setProperty("--rc-bw", `${o.width}px`);
    reportEl.style.setProperty("--rc-rad", `${o.radius}px`);
    reportEl.style.setProperty("--rc-bc", o.color);
}

function renderReceiptPreview(data) {
    reportEl.className = "report receipt";

    const niceDate = new Date(data.generatedAt).toLocaleString();
    if (generatedMeta) generatedMeta.textContent = `Generated on ${niceDate}`;

    const membersHtml = data.members.map(m => `
    <div class="member">
      <div class="left">
        <div class="role">${escapeHtml(m.role)}</div>
        <div class="name">${escapeHtml(m.name)}</div>
      </div>
      <div class="email">${m.email ? escapeHtml(m.email) : "—"}</div>
    </div>
  `).join("");

    reportEl.innerHTML = `
    <div class="top">
      <div class="title">STARTUP&nbsp;&nbsp;TEAM</div>
      <div class="sub">Technopreneurship Submission</div>
    </div>

    <div class="brand-strip"></div>

    <div class="pair">
      <div class="k">STARTUP&nbsp;&nbsp;NAME</div>
      <div class="v highlight">${escapeHtml(data.teamName)}</div>
    </div>

    <div class="pair">
      <div class="k">MEMBERS</div>
      <div class="v">3</div>
    </div>

    <div class="pair">
      <div class="k">GENERATED</div>
      <div class="v">${escapeHtml(niceDate)}</div>
    </div>

    <div class="hr"></div>

    <div class="section">
      <h4>TEAM&nbsp;&nbsp;MEMBERS</h4>
      ${membersHtml}
    </div>

    <div class="logo-area">
      <img src="${escapeHtml(_logoPreviewSrc)}" alt="CICTT Logo" onerror="this.style.display='none'">
    </div>

    <div class="footer-note">Send this PNG to your class GC / Maam Jolo.</div>
  `;

    applyBorderOptionsToPreview();
}

function dataURLToBlob(dataUrl) {
    const [meta, b64] = dataUrl.split(",");
    const mime = (meta.match(/data:(.*?);base64/) || [])[1] || "image/jpeg";
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Blob([bytes], { type: mime });
}

async function loadLogoBitmap() {
    if (_logoBitmap) return _logoBitmap;

    const hasEmbedded = typeof LOGO_DATA_URL === "string" && LOGO_DATA_URL.startsWith("data:image/");
    if (hasEmbedded) {
        _logoPreviewSrc = LOGO_DATA_URL;
        const blob = dataURLToBlob(LOGO_DATA_URL);
        if ("createImageBitmap" in window) {
            _logoBitmap = await createImageBitmap(blob);
            return _logoBitmap;
        }
        const objUrl = URL.createObjectURL(blob);
        const img = await new Promise((resolve) => {
            const im = new Image();
            im.onload = () => resolve(im);
            im.onerror = () => resolve(null);
            im.src = objUrl;
        });
        URL.revokeObjectURL(objUrl);
        _logoBitmap = img;
        return _logoBitmap;
    }

    if (location.protocol === "file:") {
        _logoBitmap = null;
        _logoPreviewSrc = DEFAULT_LOGO_URL;
        return null;
    }

    try {
        const res = await fetch(DEFAULT_LOGO_URL, { cache: "no-store" });
        if (!res.ok) return null;
        const blob = await res.blob();
        if (!blob || blob.size === 0) return null;

        if ("createImageBitmap" in window) {
            _logoBitmap = await createImageBitmap(blob);
            return _logoBitmap;
        }

        const objUrl = URL.createObjectURL(blob);
        const img = await new Promise((resolve) => {
            const im = new Image();
            im.onload = () => resolve(im);
            im.onerror = () => resolve(null);
            im.src = objUrl;
        });
        URL.revokeObjectURL(objUrl);
        _logoBitmap = img;
        return _logoBitmap;
    } catch {
        return null;
    }
}

function wrapLines(ctx, text, maxWidth) {
    const words = (text || "").split(/\s+/).filter(Boolean);
    const lines = [];
    let line = "";
    for (const w of words) {
        const test = line ? `${line} ${w}` : w;
        if (ctx.measureText(test).width <= maxWidth) line = test;
        else {
            if (line) lines.push(line);
            line = w;
        }
    }
    if (line) lines.push(line);
    return lines.length ? lines : [""];
}

function measureSpacedText(ctx, text, spacing) {
    let total = 0;
    for (let i = 0; i < text.length; i++) {
        total += ctx.measureText(text[i]).width;
        if (i !== text.length - 1) total += spacing;
    }
    return total;
}

function drawSpacedText(ctx, text, x, y, spacing, align = "left") {
    const totalW = measureSpacedText(ctx, text, spacing);
    let startX = x;
    if (align === "center") startX = x - totalW / 2;
    if (align === "right") startX = x - totalW;

    let cx = startX;
    for (let i = 0; i < text.length; i++) {
        ctx.fillText(text[i], cx, y);
        cx += ctx.measureText(text[i]).width + (i !== text.length - 1 ? spacing : 0);
    }
}

function roundedRectPath(ctx, x, y, w, h, r) {
    const rr = Math.max(0, Math.min(r, Math.min(w, h) / 2));
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
}

function setDashForStyle(ctx, style) {
    if (style === "dashed") ctx.setLineDash([12, 10]);
    else if (style === "dotted") ctx.setLineDash([2, 8]);
    else ctx.setLineDash([]);
}

function dottedRule(ctx, x1, x2, y) {
    ctx.save();
    ctx.strokeStyle = "#d7dde8";
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 6]);
    ctx.beginPath();
    ctx.moveTo(x1, y);
    ctx.lineTo(x2, y);
    ctx.stroke();
    ctx.restore();
}

function drawRightHighlightedLines(ctx, value, rightX, y, maxWidth) {
    ctx.font = '900 18px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    const lines = wrapLines(ctx, value, maxWidth);

    const padX = 10;
    const padY = 6;
    const radius = 10;
    const lineGap = 24;

    for (const line of lines) {
        const m = ctx.measureText(line);
        const ascent = m.actualBoundingBoxAscent || 14;
        const descent = m.actualBoundingBoxDescent || 4;

        const rectW = m.width + padX * 2;
        const rectH = ascent + descent + padY * 2;

        const rectX = rightX - rectW;
        const rectY = y - ascent - padY;

        ctx.fillStyle = "#fff1e9";
        ctx.strokeStyle = "#f9c2ac";
        ctx.lineWidth = 1;

        roundedRectPath(ctx, rectX, rectY, rectW, rectH, radius);
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = "#111827";
        ctx.textAlign = "right";
        ctx.fillText(line, rightX - padX, y);
        ctx.textAlign = "left";

        y += lineGap;
    }

    return Math.max(34, lines.length * lineGap);
}

function buildReceiptCanvas(data, borderOpt, logoImg) {
    const dpr = window.devicePixelRatio || 1;
    const width = 900;
    const pad = 78;
    const innerW = width - pad * 2;

    const t = document.createElement("canvas");
    const tctx = t.getContext("2d");

    function computeHeight() {
        let y = pad;

        tctx.font = '900 30px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
        y += 30 + 18;

        tctx.font = '700 16px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
        y += 16 + 18;

        y += 28;
        y += 34 + 34 + 32;
        y += 40 + 30;

        for (const m of data.members) {
            y += 24;
            tctx.font = '900 22px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
            const nameLines = wrapLines(tctx, m.name, innerW * 0.62);
            y += nameLines.length * 26 + 10;
            y += 38;
        }

        y += 40;
        const minPortrait = Math.ceil(width * 1.18);
        return Math.max(y + pad, minPortrait);
    }

    const height = computeHeight();

    const canvas = document.createElement("canvas");
    canvas.width = Math.floor(width * dpr);
    canvas.height = Math.floor(height * dpr);

    const ctx = canvas.getContext("2d");
    ctx.scale(dpr, dpr);

    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, width, height);

    const b = borderOpt || { style: "solid", width: 6, radius: 28, color: "#F05722" };
    const borderX = 22, borderY = 22, borderW = width - 44, borderH = height - 44;

    ctx.lineWidth = b.width;
    ctx.strokeStyle = b.color;

    if (b.style === "double") {
        ctx.setLineDash([]);
        roundedRectPath(ctx, borderX, borderY, borderW, borderH, b.radius);
        ctx.stroke();
        const inset = b.width * 2.5;
        ctx.lineWidth = Math.max(2, b.width - 2);
        roundedRectPath(ctx, borderX + inset, borderY + inset, borderW - inset * 2, borderH - inset * 2, Math.max(0, b.radius - 10));
        ctx.stroke();
    } else {
        setDashForStyle(ctx, b.style);
        roundedRectPath(ctx, borderX, borderY, borderW, borderH, b.radius);
        ctx.stroke();
    }
    ctx.setLineDash([]);

    let y = pad;

    ctx.fillStyle = "#111827";
    ctx.font = '900 30px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    drawSpacedText(ctx, "STARTUP  TEAM", width / 2, y, 4, "center");
    y += 32;

    ctx.fillStyle = "#5f6b82";
    ctx.font = '700 16px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    ctx.textAlign = "center";
    ctx.fillText("Technopreneurship Submission", width / 2, y);
    ctx.textAlign = "left";
    y += 22;

    const grad = ctx.createLinearGradient(pad, y, width - pad, y);
    grad.addColorStop(0, "#9D191C");
    grad.addColorStop(1, "#F05722");
    ctx.strokeStyle = grad;
    ctx.lineWidth = 10;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(pad, y);
    ctx.lineTo(width - pad, y);
    ctx.stroke();
    y += 34;

    const leftX = pad;
    const rightX = width - pad;

    ctx.fillStyle = "#667085";
    ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    drawSpacedText(ctx, "STARTUP  NAME", leftX, y, 2, "left");

    const used = drawRightHighlightedLines(ctx, data.teamName, rightX, y, innerW * 0.55);
    y += used;

    ctx.fillStyle = "#667085";
    ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    drawSpacedText(ctx, "MEMBERS", leftX, y, 2, "left");

    ctx.textAlign = "right";
    ctx.fillStyle = "#111827";
    ctx.font = '900 18px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    ctx.fillText("3", rightX, y);
    ctx.textAlign = "left";
    y += 34;

    const niceDate = new Date(data.generatedAt).toLocaleString();
    ctx.fillStyle = "#667085";
    ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    drawSpacedText(ctx, "GENERATED", leftX, y, 2, "left");

    ctx.textAlign = "right";
    ctx.fillStyle = "#111827";
    ctx.font = '900 16px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    ctx.fillText(niceDate, rightX, y);
    ctx.textAlign = "left";
    y += 26;

    dottedRule(ctx, leftX, rightX, y);
    y += 42;

    ctx.fillStyle = "#111827";
    ctx.font = '900 14px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    drawSpacedText(ctx, "TEAM  MEMBERS", leftX, y, 3, "left");
    y += 30;

    for (const m of data.members) {
        ctx.fillStyle = "#667085";
        ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
        drawSpacedText(ctx, m.role, leftX, y, 2, "left");

        ctx.textAlign = "right";
        ctx.fillStyle = "#667085";
        ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
        ctx.fillText(m.email || "—", rightX, y);
        ctx.textAlign = "left";
        y += 24;

        ctx.fillStyle = "#111827";
        ctx.font = '900 22px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
        const nameLines = wrapLines(ctx, m.name, innerW * 0.62);
        for (const line of nameLines) {
            ctx.fillText(line, leftX, y);
            y += 26;
        }

        y += 10;
        dottedRule(ctx, leftX, rightX, y);
        y += 38;
    }

    const footerY = height - pad + 18;
    const availableTop = y;
    const availableBottom = footerY - 30;
    const availableH = availableBottom - availableTop;

    if (availableH > 70) {
        if (logoImg) {
            const iw = (logoImg.naturalWidth || logoImg.width || 1);
            const ih = (logoImg.naturalHeight || logoImg.height || 1);

            const maxW = innerW * 0.92;
            const maxH = Math.min(availableH * 0.9, 460);

            let dw = maxW;
            let dh = (ih / iw) * dw;

            if (dh > maxH) {
                dh = maxH;
                dw = (iw / ih) * dh;
            }

            const dx = (width - dw) / 2;
            const dy = availableTop + (availableH - dh) / 2;

            ctx.save();
            ctx.globalAlpha = 0.35;
            ctx.filter = "none";
            ctx.drawImage(logoImg, dx, dy, dw, dh);
            ctx.restore();
        } else {
            ctx.save();
            ctx.globalAlpha = 0.08;
            ctx.fillStyle = "#111827";
            ctx.textAlign = "center";
            ctx.font = '900 80px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
            ctx.fillText("CICTT", width / 2, availableTop + availableH / 2);
            ctx.restore();
            ctx.textAlign = "left";
        }
    }

    ctx.fillStyle = "#667085";
    ctx.font = '700 13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace';
    ctx.textAlign = "center";
    ctx.fillText("Send this PNG to your class GC / teacher.", width / 2, footerY);
    ctx.textAlign = "left";

    return canvas;
}

function saveCanvasAs(canvas, filename) {
    canvas.toBlob((blob) => {
        if (!blob) return;
        const url = URL.createObjectURL(blob);

        const a = document.createElement("a");
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        a.remove();

        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }, "image/png", 1.0);
}

function wireBorderControls() {
    const controls = [borderStyle, borderWidth, borderRadius, borderColor].filter(Boolean);
    for (const el of controls) {
        el.addEventListener("input", applyBorderOptionsToPreview);
        el.addEventListener("change", applyBorderOptionsToPreview);
    }
}

form?.addEventListener("submit", async (e) => {
    e.preventDefault();
    if (errorBox) errorBox.textContent = "";

    const data = getTeamData();
    const err = validate(data);

    if (err) {
        if (errorBox) errorBox.textContent = err;
        showToast("Complete the required fields.");
        return;
    }

    lastData = data;

    await loadLogoBitmap();
    renderReceiptPreview(data);

    previewSection?.classList.remove("hidden");
    previewSection?.scrollIntoView({ behavior: "smooth", block: "start" });

    showToast("Preview ready ✅");
});

resetBtn?.addEventListener("click", () => {
    form?.reset();
    if (errorBox) errorBox.textContent = "";
    previewSection?.classList.add("hidden");
    if (reportEl) {
        reportEl.innerHTML = "";
        reportEl.className = "report";
    }
    lastData = null;
    showToast("Form cleared.");
});

pngBtn?.addEventListener("click", async () => {
    if (!lastData) return showToast("Generate the preview first.");

    const safe = (lastData.teamName || "startup").replace(/[^\w\-]+/g, "_").slice(0, 40);
    const b = getBorderOptions();

    const logo = await loadLogoBitmap();

    if (location.protocol === "file:" && !logo) {
        showToast("To include logo in direct download: embed LOGO_DATA_URL (base64).");
    }

    const canvas = buildReceiptCanvas(lastData, b, logo);
    saveCanvasAs(canvas, `startup_team_${safe}.png`);
    showToast("PNG downloaded ✅");
});

wireBorderControls();
